"use client";
import{useCallback,useEffect,useState}from"react";import Link from"next/link";import{migrateLegacyQueue,readQueue,syncQueue,SYNC_EVENT,type QueueRecord}from"../../lib/offline-sync";
export function SyncStatus(){const[items,setItems]=useState<QueueRecord[]>([]);const[online,setOnline]=useState(true);const[working,setWorking]=useState(false);const refresh=useCallback(async()=>{setOnline(navigator.onLine);setItems(await readQueue())},[]);const run=useCallback(async()=>{if(!navigator.onLine)return;setWorking(true);await syncQueue();setWorking(false);await refresh()},[refresh]);useEffect(()=>{let active=true;const start=async()=>{await migrateLegacyQueue();if(active){await refresh();await run()}};void start();const change=()=>void refresh(),connected=()=>void run(),message=(event:MessageEvent)=>{if(event.data?.type==="SYNC_REQUEST")void run()};window.addEventListener(SYNC_EVENT,change);window.addEventListener("online",connected);window.addEventListener("offline",change);navigator.serviceWorker?.addEventListener("message",message);const timer=window.setInterval(()=>void run(),60000);return()=>{active=false;window.removeEventListener(SYNC_EVENT,change);window.removeEventListener("online",connected);window.removeEventListener("offline",change);navigator.serviceWorker?.removeEventListener("message",message);window.clearInterval(timer)}},[refresh,run]);const failed=items.filter(item=>item.status==="failed").length;if(online&&!items.length&&!working)return null;return <Link href="/sync" className={`sync-indicator ${!online?"offline":failed?"failed":"pending"}`} role="status"><span>{!online?"Offline":working?"Syncing":failed?`${failed} failed`:`${items.length} pending`}</span><small>{!online?"Saves stay on this device":"Open sync status"}</small></Link>}
